// ATOM2_W13 · Painel de indicadores do funil (GET /webhook/atom2-painel?k=QA_TOKEN).
// Só conta o que está registrado nas tabelas atom2_* (nada estimado). Registros de teste (c_teste_*) ficam fora dos números.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const brl = (v) => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const pct = (a, b) => (b ? Math.round((a / b) * 1000) / 10 + '%' : '—');
const real = (x) => x && x.company_id && !String(x.company_id).startsWith('c_teste_');
const ETAPAS = [['F1', 'Importada'], ['F2', 'Diagnóstico N1'], ['F3', 'QA aprovado'], ['F4', 'No CRM'], ['F5', 'Em cadência'], ['F6', 'Respondeu'], ['F7', 'Qualificado'], ['F8', 'Diagnóstico N2 / reunião'], ['F9', 'Proposta'], ['F10', 'Negociação'], ['F11', 'Encerrado (ganho ou perdido)']];
const conta = (lista, chave) => lista.reduce((m, x) => { const k = x[chave] || '—'; m[k] = (m[k] || 0) + 1; return m; }, {});

function indicadores(empresas, auditorias, mensagens, propostas, eventos) {
  const E = (empresas || []).filter(real), A = (auditorias || []).filter(real), M = (mensagens || []).filter(real), P = (propostas || []).filter(real), V = (eventos || []).filter(real);
  const saida = M.filter((m) => m.direcao === 'saida'), entrada = M.filter((m) => m.direcao === 'entrada');
  const abordadas = new Set(saida.filter((m) => m.passo === 'D1' && ['simulada', 'pronta_envio', 'enviada'].includes(m.status)).map((m) => m.company_id));
  const responderam = new Set(entrada.map((m) => m.company_id));
  const aceitas = P.filter((p) => p.status === 'aceita');
  return {
    empresas: E.length, outbound: E.filter((e) => e.fluxo !== 'receptivo').length, receptivo: E.filter((e) => e.fluxo === 'receptivo').length,
    porEtapa: conta(E.filter((e) => e.fluxo !== 'receptivo'), 'funil_etapa'), receptivoPorEtapa: conta(E.filter((e) => e.fluxo === 'receptivo'), 'funil_etapa'),
    optOut: E.filter((e) => e.opt_out === true || String(e.opt_out) === 'true').length,
    qa: conta(A, 'qa_status'), faixas: conta(A.filter((a) => a.faixa && a.status !== 'falha'), 'faixa'),
    saidaPorStatus: conta(saida, 'status'), saidaPorPasso: conta(saida, 'passo'), intencoes: conta(entrada, 'intencao'),
    abordadas: abordadas.size, responderam: [...responderam].filter((c) => abordadas.has(c)).length,
    propostas: P.length, aceitas: aceitas.length, valorAceito: aceitas.reduce((s, p) => s + Number(p.valor_total || 0), 0), valorProposto: P.reduce((s, p) => s + Number(p.valor_total || 0), 0),
    diagnosticosAbertos: V.filter((v) => v.tipo === 'DIAGNOSTICO_ABERTO').length, falhasCrm: V.filter((v) => v.tipo === 'CRM_FALHA').length,
    bloqueadas: saida.filter((m) => m.status === 'bloqueada').length
  };
}

function tabela(titulo, mapa, rotulos) {
  const linhas = (rotulos || Object.keys(mapa).sort().map((k) => [k, k])).filter(([k]) => mapa[k]).map(([k, r]) => `<tr><td>${esc(r)}</td><td class="n">${mapa[k]}</td></tr>`).join('');
  return `<section class="card"><h2>${esc(titulo)}</h2>${linhas ? `<table>${linhas}</table>` : '<p class="mut">Sem registros.</p>'}</section>`;
}
function painelHtml(ind, modo, agoraISO) {
  const kpi = (r, v, d) => `<div class="kpi"><div class="v">${v}</div><div class="r">${esc(r)}</div>${d ? `<div class="d">${esc(d)}</div>` : ''}</div>`;
  const corpo = `<h1>Funil comercial · ATOM</h1><p class="sub">Atualizado em ${esc(new Date(agoraISO || Date.now()).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }))} · modo ${esc(modo)} · registros de teste não entram nos números.</p>
<div class="kpis">${kpi('Empresas na base', ind.empresas, ind.outbound + ' ativas · ' + ind.receptivo + ' receptivas')}${kpi('Abordadas (D1)', ind.abordadas)}${kpi('Responderam', ind.responderam, 'taxa ' + pct(ind.responderam, ind.abordadas))}${kpi('Propostas', ind.propostas, brl(ind.valorProposto))}${kpi('Aceitas', ind.aceitas, brl(ind.valorAceito) + ' · ' + pct(ind.aceitas, ind.propostas))}${kpi('Opt-out', ind.optOut)}</div>
<div class="grid">
${tabela('Prospecção ativa por etapa', ind.porEtapa, ETAPAS)}
${tabela('Receptivo por etapa', ind.receptivoPorEtapa)}
${tabela('QA dos diagnósticos', ind.qa)}
${tabela('Faixa do score N1', ind.faixas)}
${tabela('Mensagens de saída por status', ind.saidaPorStatus)}
${tabela('Mensagens de saída por passo', ind.saidaPorPasso)}
${tabela('Respostas por intenção', ind.intencoes)}
<section class="card"><h2>Alertas</h2><table><tr><td>Mensagens bloqueadas (trava de preço/termos/canal)</td><td class="n">${ind.bloqueadas}</td></tr><tr><td>Falhas no Pipedrive</td><td class="n">${ind.falhasCrm}</td></tr><tr><td>Diagnósticos abertos pelo lead</td><td class="n">${ind.diagnosticosAbertos}</td></tr></table></section>
</div>`;
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Funil comercial · ATOM</title>
<style>:root{--bg:#f6f7f9;--card:#fff;--tx:#1d2330;--mut:#5d6677;--bd:#e3e6ec;--pri:#2f5bd3}
@media (prefers-color-scheme:dark){:root{--bg:#12151b;--card:#1b2029;--tx:#e8ebf1;--mut:#9aa3b2;--bd:#2c3340;--pri:#7c9cff}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.5 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}main{max-width:1100px;margin:0 auto;padding:28px 16px 56px}
h1{font-size:24px;margin:0 0 4px}h2{font-size:15px;margin:0 0 8px}.sub,.mut{color:var(--mut)}.sub{margin:0 0 18px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:0 0 16px}.kpi{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:14px}.kpi .v{font-size:26px;font-weight:700;color:var(--pri)}.kpi .r{font-weight:600}.kpi .d{font-size:13px;color:var(--mut)}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}.card{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:14px}
table{width:100%;border-collapse:collapse}td{padding:4px 0;border-bottom:1px solid var(--bd)}td.n{text-align:right;font-variant-numeric:tabular-nums;font-weight:600}</style></head><body><main>${corpo}</main></body></html>`;
}


const cfg = $('Ler config').all().map((i) => i.json);
const tok = (cfg.find((r) => r && r.chave === 'QA_TOKEN') || {}).valor;
const k = String((($('Painel (GET)').first().json.query) || {}).k || '');
if (!tok || k !== String(tok)) return [{ json: { status: 403, html: '<!doctype html><meta charset="utf-8"><title>Acesso negado</title><p>Acesso negado.</p>' } }];
const modos = cfg.filter((r) => r && r.chave === 'MODO_EXECUCAO').map((r) => String(r.valor).toUpperCase());
const modo = modos.length && modos.every((m) => m === 'PRODUCAO') ? 'PRODUCAO' : 'SIMULACAO';
const ind = indicadores($('Ler empresas').all().map((i) => i.json), $('Ler auditorias').all().map((i) => i.json), $('Ler mensagens').all().map((i) => i.json), $('Ler propostas').all().map((i) => i.json), $('Ler eventos').all().map((i) => i.json));
return [{ json: { status: 200, html: painelHtml(ind, modo, new Date().toISOString()) } }];
